//
// The channel table (spro_board.c) is generated by ./spro from boards/<board>.toml.
// A backend (kits/io/sproHal/backends/<name>) implements the four functions
// below on raw values; inversion and scaling are done by sproHal_Hal.c:
//
//   di  raw 0/1                       -> value = raw ^ invert
//   do  value 0/1                     -> raw = value ^ invert
//   ai  raw 0..raw_max                -> value = lo + raw / raw_max * (hi - lo)
//   ao  value lo..hi                  -> raw duty 0..1 = (value - lo) / (hi - lo)
//
#ifndef SPRO_HAL_H
#define SPRO_HAL_H

#include <stdint.h>

enum { SPRO_KIND_NONE = 0, SPRO_KIND_DI = 1, SPRO_KIND_DO = 2, SPRO_KIND_AI = 3, SPRO_KIND_AO = 4 };
enum { SPRO_PULL_NONE = 0, SPRO_PULL_UP = 1, SPRO_PULL_DOWN = 2 };
enum { SPRO_HAL_OK = 0, SPRO_HAL_NO_CHANNEL = 1, SPRO_HAL_WRONG_KIND = 2, SPRO_HAL_IO_ERROR = 3 };

typedef struct
{
  const char* name;     // DI1, DO1, AI1, AO1, RELAY_FAN ...
  uint8_t     kind;     // SPRO_KIND_*
  uint8_t     invert;   // di/do: logical = !electrical
  uint8_t     pull;     // di: SPRO_PULL_*
  int         pin;      // esp32: GPIO number; gpiod/sysfs: line / gpio number; -1 = unused
  const char* dev;      // gpiod: "gpiochip0"; ai: IIO file; ao: PWM dir; NULL = default
  float       rawMax;   // ai: full-scale raw reading
  float       lo, hi;   // ai/ao: engineering range
  uint32_t    pwmHz;    // ao: PWM frequency (0 = DAC/backend default)
  float       initial;  // do/ao: value at start; sim di/ai: initial input
} spro_channel_t;

// generated: spro_board.c
extern const char* const    spro_board_name;
extern const spro_channel_t spro_board_channels[];
extern const int            spro_board_channel_count;
extern const char* const    spro_board_serial[];
extern const int            spro_board_serial_count;

// backend
extern const char* const spro_hal_backend_name;
int spro_hal_backend_open(int index, const spro_channel_t* c);                // 0 = ok
int spro_hal_backend_read(int index, const spro_channel_t* c, float* raw);   // 0 = ok
int spro_hal_backend_write(int index, const spro_channel_t* c, float raw);   // 0 = ok

#endif
